// Created: 2026-09-03 by Constructor Tech
//! Gateway error model for OAGW.
//!
//! Every error generated by OAGW itself is rendered as an RFC 9457
//! `application/problem+json` body whose `type` member carries the GTS
//! identifier documented in `DESIGN.md` §3.3, and always carries
//! `X-OAGW-Error-Source: gateway` ([`ERROR_SOURCE_HEADER`]).
//!
//! Upstream responses are never rewritten: they are passed through with
//! `X-OAGW-Error-Source: upstream` (see `proxy.rs`).

use axum::http::HeaderValue;
use axum::response::{IntoResponse, Response};
use serde_json::{Map, Value};

/// Value of the `X-OAGW-Error-Source` header on gateway-generated errors.
pub const ERROR_SOURCE_HEADER: &str = "X-OAGW-Error-Source";
/// Value of the `X-OAGW-Error-Source` header on passthrough upstream errors.
pub const ERROR_SOURCE_GATEWAY: &str = "gateway";
/// Value of the `X-OAGW-Error-Source` header on upstream-sourced responses.
pub const ERROR_SOURCE_UPSTREAM: &str = "upstream";
/// Response header carrying the correlation identifier of a proxy request.
pub const TRACE_ID_HEADER: &str = "x-oagw-trace-id";

/// The catalogue of gateway error types, with their HTTP status and GTS `type`.
///
/// Mirrors the error table of `DESIGN.md` §3.3 plus the two CORS rejections
/// documented in `ADR/0004-cors.md`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ErrorKind {
    /// General request/route validation failure.
    Validation,
    /// `X-OAGW-Target-Host` required but missing.
    MissingTargetHost,
    /// `X-OAGW-Target-Host` is not a bare hostname or IP.
    InvalidTargetHost,
    /// `X-OAGW-Target-Host` does not name a configured endpoint.
    UnknownTargetHost,
    /// Authentication against the upstream failed.
    AuthFailed,
    /// CORS preflight/actual request origin is not allowed.
    CorsOriginNotAllowed,
    /// CORS actual request method is not allowed.
    CorsMethodNotAllowed,
    /// No matching route.
    RouteNotFound,
    /// Referenced resource does not exist.
    ResourceNotFound,
    /// Alias already registered for this tenant.
    AliasConflict,
    /// Route match rule duplicates an existing route.
    RouteConflict,
    /// A referenced upstream does not exist.
    UpstreamNotFound,
    /// Plugin still referenced by an upstream or route.
    PluginInUse,
    /// Referenced plugin does not exist.
    PluginNotFound,
    /// Request payload exceeds the configured limit.
    PayloadTooLarge,
    /// Rate limit exhausted.
    RateLimitExceeded,
    /// A `cred://` reference could not be resolved.
    SecretNotFound,
    /// Upstream spoke a protocol this gateway does not accept.
    ProtocolError,
    /// Upstream returned an error response.
    DownstreamError,
    /// Streaming connection aborted mid-flight.
    StreamAborted,
    /// The resolved endpoint is refused by the SSRF policy.
    EndpointForbidden,
    /// Upstream link could not be established.
    LinkUnavailable,
    /// Circuit breaker tripped for this upstream.
    CircuitBreakerOpen,
    /// Establishing the upstream connection timed out.
    ConnectionTimeout,
    /// The upstream request timed out.
    RequestTimeout,
    /// The upstream connection went idle mid-exchange.
    IdleTimeout,
    /// Upstream rejected an upgrade the gateway cannot bridge.
    UpgradeUnsupported,
}

impl ErrorKind {
    /// The GTS error `type` identifier for this kind.
    #[must_use]
    pub fn type_id(self) -> &'static str {
        match self {
            Self::Validation => "validation.error.v1",
            Self::MissingTargetHost => "routing.missing_target_host.v1",
            Self::InvalidTargetHost => "routing.invalid_target_host.v1",
            Self::UnknownTargetHost => "routing.unknown_target_host.v1",
            Self::AuthFailed => "auth.failed.v1",
            Self::CorsOriginNotAllowed => "cors.origin_not_allowed.v1",
            Self::CorsMethodNotAllowed => "cors.method_not_allowed.v1",
            Self::EndpointForbidden => "upstream.endpoint_forbidden.v1",
            Self::RouteNotFound => "route.not_found.v1",
            Self::ResourceNotFound => "validation.error.v1",
            Self::AliasConflict => "validation.error.v1",
            Self::RouteConflict => "validation.error.v1",
            Self::UpstreamNotFound => "validation.error.v1",
            Self::PluginInUse => "plugin.in_use.v1",
            Self::PluginNotFound => "plugin.not_found.v1",
            Self::PayloadTooLarge => "payload.too_large.v1",
            Self::RateLimitExceeded => "rate_limit.exceeded.v1",
            Self::SecretNotFound => "secret.not_found.v1",
            Self::ProtocolError => "protocol.error.v1",
            Self::DownstreamError => "downstream.error.v1",
            Self::StreamAborted => "stream.aborted.v1",
            Self::LinkUnavailable => "link.unavailable.v1",
            Self::CircuitBreakerOpen => "circuit_breaker.open.v1",
            Self::ConnectionTimeout => "timeout.connection.v1",
            Self::RequestTimeout => "timeout.request.v1",
            Self::IdleTimeout => "timeout.idle.v1",
            Self::UpgradeUnsupported => "protocol.error.v1",
        }
    }

    /// The HTTP status code for this kind.
    #[must_use]
    pub fn status(self) -> u16 {
        match self {
            Self::Validation
            | Self::MissingTargetHost
            | Self::InvalidTargetHost
            | Self::UnknownTargetHost => 400,
            // ADR 0004: a disallowed origin or method on an actual request is
            // a 403, not a 400.
            Self::CorsOriginNotAllowed | Self::CorsMethodNotAllowed | Self::EndpointForbidden => {
                403
            }
            Self::AuthFailed => 401,
            Self::ResourceNotFound | Self::RouteNotFound | Self::UpstreamNotFound => 404,
            Self::AliasConflict | Self::RouteConflict | Self::PluginInUse => 409,
            Self::PayloadTooLarge => 413,
            Self::RateLimitExceeded => 429,
            Self::SecretNotFound => 500,
            Self::DownstreamError | Self::ProtocolError | Self::StreamAborted | Self::UpgradeUnsupported => 502,
            Self::LinkUnavailable | Self::CircuitBreakerOpen | Self::PluginNotFound => 503,
            Self::ConnectionTimeout | Self::RequestTimeout | Self::IdleTimeout => 504,
        }
    }

    /// The RFC 9457 `title` member for this kind.
    #[must_use]
    pub fn title(self) -> &'static str {
        match self {
            Self::Validation => "Validation Error",
            Self::MissingTargetHost => "Missing Target Host Header",
            Self::InvalidTargetHost => "Invalid Target Host Format",
            Self::UnknownTargetHost => "Unknown Target Host",
            Self::AuthFailed => "Authentication Failed",
            Self::CorsOriginNotAllowed => "CORS Origin Not Allowed",
            Self::CorsMethodNotAllowed => "CORS Method Not Allowed",
            Self::EndpointForbidden => "Upstream Endpoint Not Allowed",
            Self::RouteNotFound => "Route Not Found",
            Self::ResourceNotFound => "Resource Not Found",
            Self::AliasConflict => "Alias Conflict",
            Self::RouteConflict => "Route Conflict",
            Self::UpstreamNotFound => "Upstream Not Found",
            Self::PluginInUse => "Plugin In Use",
            Self::PluginNotFound => "Plugin Not Found",
            Self::PayloadTooLarge => "Payload Too Large",
            Self::RateLimitExceeded => "Rate Limit Exceeded",
            Self::SecretNotFound => "Secret Not Found",
            Self::ProtocolError => "Protocol Error",
            Self::DownstreamError => "Downstream Error",
            Self::StreamAborted => "Stream Aborted",
            Self::LinkUnavailable => "Link Unavailable",
            Self::CircuitBreakerOpen => "Circuit Breaker Open",
            Self::ConnectionTimeout => "Connection Timeout",
            Self::RequestTimeout => "Request Timeout",
            Self::IdleTimeout => "Idle Timeout",
            Self::UpgradeUnsupported => "Upgrade Unsupported",
        }
    }

    /// Whether the error type table marks this error as retriable.
    #[must_use]
    pub fn retriable(self) -> bool {
        matches!(
            self,
            Self::RateLimitExceeded
                | Self::LinkUnavailable
                | Self::CircuitBreakerOpen
                | Self::ConnectionTimeout
                | Self::RequestTimeout
                | Self::IdleTimeout
        )
    }
}

/// Request-scoped context attached to a problem document.
#[derive(Debug, Clone, Default)]
pub struct ProblemContext {
    upstream_id: Option<String>,
    host: Option<String>,
    path: Option<String>,
    retry_after_seconds: Option<u64>,
    trace_id: Option<String>,
    extra: Option<Map<String, Value>>,
}

/// A gateway error that renders as an RFC 9457 problem document.
#[derive(Debug, Clone, thiserror::Error)]
#[error("{kind:?}: {detail}")]
pub struct OagwError {
    kind: ErrorKind,
    detail: String,
    /// Boxed: the problem context is rarely populated, so the error stays
    /// cheap to move through every fallible helper of the pipeline.
    ctx: Box<ProblemContext>,
}

impl OagwError {
    /// Creates a gateway error of `kind` with a human readable `detail`.
    #[must_use]
    pub fn new(kind: ErrorKind, detail: impl Into<String>) -> Self {
        Self {
            kind,
            detail: detail.into(),
            ctx: Box::new(ProblemContext::default()),
        }
    }

    /// The error kind of this error.
    #[must_use]
    pub const fn kind(&self) -> ErrorKind {
        self.kind
    }

    /// Attaches the affected upstream GTS identifier.
    #[must_use]
    pub fn with_upstream_id(mut self, upstream_id: impl Into<String>) -> Self {
        self.ctx.upstream_id = Some(upstream_id.into());
        self
    }

    /// Attaches the resolved upstream host (alias or endpoint host).
    #[must_use]
    pub fn with_host(mut self, host: impl Into<String>) -> Self {
        self.ctx.host = Some(host.into());
        self
    }

    /// Attaches the request path used as the RFC 9457 `instance`.
    #[must_use]
    pub fn with_instance(mut self, instance: impl Into<String>) -> Self {
        self.ctx.path = Some(instance.into());
        self
    }

    /// Attaches retry guidance, also emitted as the `Retry-After` header.
    #[must_use]
    pub fn with_retry_after(mut self, seconds: u64) -> Self {
        self.ctx.retry_after_seconds = Some(seconds);
        self
    }

    /// Attaches the correlation identifier.
    #[must_use]
    pub fn with_trace_id(mut self, trace_id: impl Into<String>) -> Self {
        self.ctx.trace_id = Some(trace_id.into());
        self
    }

    /// Adds a free-form extension member to the problem document.
    #[must_use]
    pub fn with_extra(mut self, key: &str, value: Value) -> Self {
        self.ctx
            .extra
            .get_or_insert_with(Map::new)
            .insert(key.to_owned(), value);
        self
    }

    /// Renders the problem document as JSON, without the transport framing.
    #[must_use]
    pub fn to_problem(&self) -> Value {
        let mut body = Map::new();
        body.insert(
            "type".to_owned(),
            Value::String(format!("{}{}", crate::gts::ERROR_TYPE_PREFIX, self.kind.type_id())),
        );
        body.insert("title".to_owned(), Value::String(self.kind.title().to_owned()));
        body.insert("status".to_owned(), Value::from(self.kind.status()));
        body.insert("detail".to_owned(), Value::String(self.detail.clone()));
        if let Some(instance) = &self.ctx.path {
            body.insert("instance".to_owned(), Value::String(instance.clone()));
        }
        if let Some(upstream_id) = &self.ctx.upstream_id {
            body.insert("upstream_id".to_owned(), Value::String(upstream_id.clone()));
        }
        if let Some(host) = &self.ctx.host {
            body.insert("host".to_owned(), Value::String(host.clone()));
        }
        if let Some(retry_after) = self.ctx.retry_after_seconds {
            body.insert("retry_after_seconds".to_owned(), Value::from(retry_after));
        }
        if let Some(trace_id) = &self.ctx.trace_id {
            body.insert("trace_id".to_owned(), Value::String(trace_id.clone()));
        }
        if let Some(extra) = &self.ctx.extra {
            for (key, value) in extra {
                body.insert(key.clone(), value.clone());
            }
        }
        Value::Object(body)
    }
}

impl IntoResponse for OagwError {
    fn into_response(self) -> Response {
        let status = axum::http::StatusCode::from_u16(self.kind.status())
            .unwrap_or(axum::http::StatusCode::INTERNAL_SERVER_ERROR);
        let retry_after = self.ctx.retry_after_seconds.map(|s| s.to_string());
        let trace_id = self.ctx.trace_id.clone();
        let body = self.to_problem();

        let mut response = (status, axum::Json(body)).into_response();
        response
            .headers_mut()
            .insert("content-type", "application/problem+json".parse().expect("valid mime"));
        let headers = response.headers_mut();
        headers.insert(
            axum::http::HeaderName::from_lowercase(b"x-oagw-error-source").expect("valid header name"),
            ERROR_SOURCE_GATEWAY
                .parse()
                .expect("static header value"),
        );
        if let Some(retry_after) = retry_after
            && let Ok(value) = HeaderValue::from_str(&retry_after) {
                headers.insert(axum::http::header::RETRY_AFTER, value);
            }
        if let Some(trace_id) = trace_id
            && let Ok(value) = HeaderValue::from_str(&trace_id) {
                headers.insert(axum::http::HeaderName::from_static(TRACE_ID_HEADER), value);
            }
        response
    }
}

/// A new trace identifier for a proxy request.
#[must_use]
pub fn new_trace_id() -> String {
    uuid::Uuid::new_v4().to_string()
}

/// Convenience constructor for the 409 `PluginInUse` problem document.
///
/// `detail` names the upstreams/routes still referencing the plugin, matching
/// the shape documented in `ADR/0001-request-routing.md`.
#[must_use]
pub fn plugin_in_use(upstream_refs: &[String], route_refs: &[String]) -> OagwError {
    let detail = format!(
        "Plugin is referenced by {} upstream(s) and {} route(s)",
        upstream_refs.len(),
        route_refs.len()
    );
    OagwError::new(ErrorKind::PluginInUse, detail).with_extra(
        "referenced_by",
        serde_json::json!({ "upstreams": upstream_refs, "routes": route_refs }),
    )
}

/// Convenience constructor for a 400 `ValidationError` problem document.
#[must_use]
pub fn validation(detail: impl Into<String>) -> OagwError {
    OagwError::new(ErrorKind::Validation, detail)
}

#[cfg(test)]
#[cfg_attr(coverage_nightly, coverage(off))]
mod tests {
    use super::*;

    #[test]
    fn rate_limit_problem_carries_type_status_and_retry_after() {
        let err = OagwError::new(ErrorKind::RateLimitExceeded, "too many requests")
            .with_host("api.openai.com")
            .with_instance("/oagw/v1/proxy/api.openai.com/v1/x")
            .with_retry_after(15);

        let problem = err.to_problem();
        assert_eq!(
            problem["type"],
            "gts.cf.core.errors.err.v1~cf.oagw.rate_limit.exceeded.v1"
        );
        assert_eq!(problem["status"], 429);
        assert_eq!(problem["retry_after_seconds"], 15);
        assert_eq!(problem["host"], "api.openai.com");
        assert_eq!(problem["instance"], "/oagw/v1/proxy/api.openai.com/v1/x");
    }

    #[test]
    fn problem_in_use_reports_reference_counts() {
        let err = plugin_in_use(
            &[crate::gts::upstream_id(uuid::Uuid::new_v4())],
            &[],
        );
        assert_eq!(err.kind().status(), 409);
        assert_eq!(
            err.to_problem()["type"],
            "gts.cf.core.errors.err.v1~cf.oagw.plugin.in_use.v1"
        );
    }

    #[test]
    fn response_sets_problem_content_type_and_error_source() {
        let response = OagwError::new(ErrorKind::RouteNotFound, "no route").into_response();
        assert_eq!(response.status(), 404);
        assert_eq!(
            response
                .headers()
                .get("content-type")
                .and_then(|v| v.to_str().ok()),
            Some("application/problem+json")
        );
        assert_eq!(
            response
                .headers()
                .get("x-oagw-error-source")
                .and_then(|v| v.to_str().ok()),
            Some("gateway")
        );
    }
}
